/**
 * Standard-stream output with CPython's semantics.
 *
 * Two details matter for byte-exact parity:
 *   1. Writes must be synchronous. CPython flushes on exit; `process.stdout`
 *      is asynchronous for pipes, so a plain `console.log` followed by
 *      `process.exit()` can truncate output. We use `fs.writeSync`.
 *   2. `sys.stdout` uses the strict error handler while `sys.stderr` uses
 *      `backslashreplace`, so an un-encodable lone surrogate is rendered as
 *      escape text on stderr instead of raising.
 */

import { writeSync } from 'node:fs';

import { encodeUtf8BackslashReplace, encodeUtf8SurrogateEscape } from './codecs.mjs';
import { str } from './repr.mjs';

const STDOUT_FD = 1;
const STDERR_FD = 2;

/** Write a whole buffer, tolerating partial writes and EAGAIN on pipes. */
function writeAll(fd, buffer) {
  let offset = 0;
  while (offset < buffer.length) {
    try {
      offset += writeSync(fd, buffer, offset, buffer.length - offset);
    } catch (err) {
      if (err && (err.code === 'EAGAIN' || err.code === 'EINTR')) continue;
      if (err && err.code === 'EPIPE') return; // mirror a closed downstream
      throw err;
    }
  }
}

export function writeStdout(text) {
  writeAll(STDOUT_FD, encodeUtf8SurrogateEscape(text));
}

export function writeStderr(text) {
  writeAll(STDERR_FD, encodeUtf8BackslashReplace(text));
}

/** Python's `print(...)`: `str()` each value, join with spaces, add "\n". */
export function print(...values) {
  writeStdout(values.map(str).join(' ') + '\n');
}

/** Python's `sys.exit(status)` after flushing. */
export function exit(status = 0) {
  process.exit(status);
}
