/**
 * Encode a `str` back to UTF-8 bytes with the `surrogateescape` handler:
 * lone surrogates in the U+DC80..U+DCFF range become the original raw byte.
 */
export function encodeUtf8SurrogateEscape(text) {
  const chunks = [];
  let plain = '';
  const flush = () => {
    if (plain) {
      chunks.push(Buffer.from(plain, 'utf8'));
      plain = '';
