  // The kernel terminates every entry with NUL, so drop the empty tail.
  let end = buf.length;
  while (end > 0 && buf[end - 1] === 0) end -= 1;
  const parts = [];
  let start = 0;
  for (let i = 0; i <= end; i += 1) {
    if (i === end || buf[i] === 0) {
      parts.push(buf.subarray(start, i));
      start = i + 1;
