/**
 * Default program name. `argparse` uses `os.path.basename(sys.argv[0])`, so
 * the Node port derives it from the entry script in the same way.
 */
export function getProgName() {
  const script = process.argv[1];
  if (typeof script === 'string' && script.length > 0) return basename(script);
  return ''; // CPython yields '' when sys.argv[0] is empty
}
